from __future__ import annotations as Annotations

# the single block construction graph is one canonical chain of forty four objects
KBlockPrefix = bytes.fromhex(
    ""
)
KBlockSuffix = bytes.fromhex(
    ""
)
KIdentity = b"\xe0\x6a\xf8"
KUnset = b"\xff" * 7
KBlockObjects = 44
KBlockMiddle = 1247


# the identity is the only per document value inside the block graph
def BlockMiddle(Identity: bytes = KUnset) -> bytes:
    if len(Identity) != 7:
        raise ValueError("NX block identity must be seven bytes")
    return KBlockPrefix + Identity + KBlockSuffix


# only the forty four object shape is generated and other shapes are left alone
def IsBlock(ObjectCount: int, Length: int) -> bool:
    return ObjectCount == KBlockObjects and Length == KBlockMiddle
